use anyhow::{ensure, Result};
use candle_core::{Device, Tensor};
use joshua::model::QuantizedModel;
use std::{fs::File, sync::Arc};

fn forward(model: &mut QuantizedModel, device: &Device, ids: &[u32], offset: usize) -> Result<Vec<f32>> {
    let input = Tensor::new(ids, device)?.unsqueeze(0)?;
    let out = model.forward(&input, offset)?.to_device(&Device::Cpu)?.flatten_all()?.to_vec1()?;
    ensure!(out.iter().all(|v: &f32| v.is_finite()), "nonfinite logits at {offset}");
    Ok(out)
}
fn top1(out: &[f32]) -> u32 {
    out.iter().enumerate().max_by(|a,b| a.1.total_cmp(b.1)).unwrap().0 as u32
}
fn main() -> Result<()> {
    let trace: serde_json::Value = serde_json::from_reader(File::open(
        "/tmp/joshua-backends-20261018/qwen8/cpu-fixed/trace.json")?)?;
    let ids: Vec<u32> = trace["prompt"].as_array().unwrap().iter().map(|v| v.as_u64().unwrap() as u32).collect();
    ensure!(ids.len() == 16, "expected identical 16-token prompt");
    let file = Arc::new(File::open("/home/tserica/models/qwen3-dense/Qwen3-8B-Q4_K_M.gguf")?);
    let header = joshua::gguf_ext::read_header(&mut &*file)?;
    let mmap = Arc::new(unsafe { memmap2::Mmap::map(&*file)? });
    let device = Device::new_vulkan(0)?;
    println!("base device={device:?}");
    let model = QuantizedModel::from_gguf_mmap_placed(header.to_candle_content()?, &mut &*file,
        &device, &device, Some(mmap), Some(file.clone()), 18, None)?;
    {
        let mut warm = model.new_session().unwrap();
        let mut next = top1(&forward(&mut warm, &device, &ids[..8], 0)?);
        println!("warm prefill complete");
        for step in 0..2 { next = top1(&forward(&mut warm, &device, &[next], 8+step)?); }
        println!("warm decode complete");
    }
    device.synchronize()?;
    let mut session = model.new_session().unwrap();
    for (i, chunk) in ids.chunks(8).enumerate() {
        forward(&mut session, &device, chunk, i*8)?;
        println!("base prefill tokens={}", (i+1)*8);
    }
    println!("base batched prefill passed");
    Ok(())
}

